  ": partidos e Congresso. Dá governabilidade e abre opções políticas.": ": parties and Congress. Gives governability and opens political options.",
  ": imagem no exterior. Baixa traz sanções e isolamento.": ": image abroad. Low means sanctions and isolation.",
  "Se algum chegar a zero, a campanha acaba.": "If any of them hits zero, the campaign ends.",
  "Eles também liberam ou bloqueiam escolhas da história.": "They also unlock or block story choices.",
  "Encerrar mês": "End month",
  "Quando terminar de agir, clique aqui. O mês passa: renda, combates, agitação nos estados, humor das facções e reação de outros países.": "When you're done acting, click here. The month passes: income, battles, unrest in the states, faction moods and other countries' reactions.",
