  "Cada opção mostra os efeitos embaixo. Opções cinza exigem atributos ou decisões anteriores.": "Each option shows its effects below it. Grey options require attributes or earlier decisions.",
  "Relatório do mês": "Monthly report",
  "Tudo o que aconteceu ao encerrar o mês: renda, agitação, facções, diplomacia e batalhas (toque numa batalha para ver o porquê do resultado).": "Everything that happened when the month ended: income, unrest, factions, diplomacy and battles (tap a battle to see why it went that way).",
