  "Passe o mouse (ou toque) para ver controle e agitação. Clique num estado para abrir o painel ao lado:": "Hover (or tap) to see control and unrest. Click a state to open the side panel:",
  "Painel lateral": "Side panel",
  "Mostra o estado ou exército selecionado. Sem seleção, mostra o resumo do país e as frentes de combate.": "Shows the selected state or army. With nothing selected, it shows the country summary and the battle fronts.",
