  "Voltar à visão geral": "Back to overview",
  "O Mundo Reage": "The World Reacts",
  "Estados Unidos, União Europeia e quase todos os vizinhos sul-americanos se recusam a reconhecer o novo governo. O Mercosul suspende o Brasil, bancos estrangeiros congelam linhas de crédito e o real perde um terço do valor em duas semanas.": "The United States, the European Union and almost all South American neighbors refuse to recognize the new government. Mercosur suspends Brazil, foreign banks freeze credit lines and the real loses a third of its value in two weeks.",
  "Nos supermercados, os preços sobem dia após dia. Exportadores do agronegócio — parte da sua base — ligam desesperados: contratos estão sendo cancelados.": "In supermarkets, prices rise day after day. Agribusiness exporters — part of your base — call in desperation: contracts are being canceled.",
  "Prometer eleições supervisionadas para obter reconhecimento.": "Promise supervised elections to win recognition.",
  "Buscar apoio em governos simpáticos e ignorar o Ocidente.": "Seek support from friendly governments and ignore the West.",
  "Congelar preços e decretar controle de câmbio.": "Freeze prices and impose currency controls.",
  "toque para ver por que venceu ou perdeu": "tap to see why you won or lost",
