  "Três Bandeiras": "Three Flags",
  "O cessar-fogo vira fronteira. Brasília controla o Centro-Sul; o governo constitucional, o Norte e o Nordeste; a Liga do Sul hasteia sua própria bandeira entre o Paraná e o Uruguai. Minas Gerais continua cortada por trincheiras.": "The ceasefire becomes a border. Brasília controls the Center-South; the constitutional government, the North and Northeast; the Southern League raises its own flag between Paraná and Uruguay. Minas Gerais remains cut by trenches.",
  "Diplomatas falam em \"conflito congelado\". Nas famílias separadas pela linha de frente, ninguém usa essa palavra. A guerra de separação que muitos julgavam impossível tornou-se o novo normal.": "Diplomats talk of a \"frozen conflict\". In the families split by the front line, nobody uses that word. The war of secession many thought impossible has become the new normal.",
