  "Reunir números, aliados e danos da eleição perdida antes de decidir o rumo.": "Tally the numbers, allies and damage from the lost election before choosing a course.",
  "Assumir publicamente o papel de oposição dentro da Constituição. Acalma instituições e parceiros externos; parte da base se frustra.": "Publicly take on the role of opposition within the Constitution. Calms institutions and foreign partners; part of the base is frustrated.",
  "Questionar o processo pelos canais legais — tribunais, Congresso e auditorias — sem romper com as instituições.": "Challenge the process through legal channels — courts, Congress and audits — without breaking with the institutions.",
  "Conversas reservadas sobre caminhos fora da Constituição. Golpe de Estado é crime: no jogo, este ramo tem custos pesados e pode fracassar.": "Private talks about paths outside the Constitution. A coup is a crime: in the game, this branch has heavy costs and may fail.",
  "Montar um gabinete paralelo de conselheiros. Abre as agendas de economia, diplomacia e sociedade.": "Set up a shadow cabinet of advisers. Opens the economy, diplomacy and society agendas.",
  "Organizar a bancada e ocupar o espaço de principal voz da oposição.": "Organize the caucus and become the main voice of the opposition.",
  "Trocar pureza por votos no Congresso: cargos, palanques e acordos regionais.": "Trade purity for votes in Congress: posts, platforms and regional deals.",
  "Recusar alianças de ocasião e falar só com a base fiel.": "Refuse alliances of convenience and speak only to the loyal base.",
  "Encomendar uma auditoria técnica independente. Agrada a base; os tribunais e observadores veem com desconfiança.": "Commission an independent technical audit. Pleases the base; courts and observers view it with suspicion.",
  "Contratar uma banca respeitada e trocar ataques por petições.": "Hire a respected law firm and swap attacks for petitions.",
  "Propor mandatos e limites para tribunais superiores. Mobiliza a base e abre guerra com o Judiciário.": "Propose terms and limits for the higher courts. Mobilizes the base and opens war with the Judiciary.",
  "Baixar a temperatura com tribunais e Congresso em troca de previsibilidade.": "Lower the temperature with the courts and Congress in exchange for predictability.",
  "Costurar no Congresso um projeto de anistia ampla. Ajuda no capítulo 'Nos Tribunais', mas tensiona o Judiciário.": "Stitch together a broad amnesty bill in Congress. Helps in the 'In the Courts' chapter, but strains the Judiciary.",
  "Agrados e reuniões com comandantes. Deixa rastros: a conspiração passa a constar nos autos (bloqueia a defesa limpa em 'Nos Tribunais').": "Favors and meetings with commanders. Leaves traces: the conspiracy goes on the record (blocks the clean defense in 'In the Courts').",
  "Redigir um decreto de exceção. Aumenta a chance de adesão militar — e a gravidade de um fracasso.": "Draft an emergency decree. Raises the chance of military support — and the severity of a failure.",
  "Formalizar o regime: toque de recolher, prisões e governo por decreto. Custo humano e isolamento crescentes.": "Formalize the regime: curfew, arrests and rule by decree. Growing human cost and isolation.",
  "Afastar governadores que resistem e nomear interventores militares.": "Remove resisting governors and appoint military administrators.",
  "Anunciar um calendário eleitoral supervisionado para reduzir o isolamento.": "Announce a supervised election calendar to reduce isolation.",
  "Um só estado-maior para todas as frentes.": "A single general staff for all fronts.",
  "Construção de Estado: uma carta provisória para dar forma jurídica ao regime. Poucos dentro e fora a reconhecem.": "State building: a provisional charter to give the regime legal form. Few at home or abroad recognize it.",
  "Convocação de reservistas. Mais tropas, mais medo, menos economia.": "Call-up of reservists. More troops, more fear, less economy.",
  "Concentrar forças para quebrar a resistência constitucional. Enfraquece o inimigo por alguns meses.": "Concentrate forces to break the constitutional resistance. Weakens the enemy for a few months.",
  "Controle de preços, requisições e câmbio fixo.": "Price controls, requisitions and a fixed exchange rate.",
  "Abrir uma segunda frente contra os separatistas do Sul.": "Open a second front against the southern separatists.",
  "Trégua de conveniência com os separatistas: reconhece fato consumado e divide o comando.": "A truce of convenience with the separatists: accepts the fait accompli and splits command.",
  "Ofensiva diplomática junto a governos dispostos a ignorar a ruptura.": "A diplomatic offensive with governments willing to ignore the rupture.",
  "Compromissos com entidades do agronegócio: crédito, infraestrutura e segurança no campo.": "Commitments to agribusiness groups: credit, infrastructure and rural security.",
  "Um programa de concessões e venda de estatais — aplaudido pelo mercado, combatido por sindicatos.": "A program of concessions and state-company sales — cheered by the market, fought by unions.",
  "Soja, minério e petróleo como cartas na mesa. Libera promessas de commodities também na oposição.": "Soy, ore and oil as cards on the table. Unlocks commodity promises in opposition too.",
  "Priorizar o maior comprador do Brasil: financiamento e infraestrutura.": "Prioritize Brazil's biggest buyer: financing and infrastructure.",
  "Acordos com investidores e o mercado norte-americano, com distância de Pequim.": "Deals with investors and the US market, keeping distance from Beijing.",
  "Agendas com parlamentares, think tanks e diplomatas ocidentais. Libera promessas de cooperação em defesa.": "Meetings with Western lawmakers, think tanks and diplomats. Unlocks defense-cooperation promises.",
  "Aproximação com China, Rússia e o Sul Global.": "Closer ties with China, Russia and the Global South.",
  "Agenda regional com governadores de fronteira e vizinhos.": "A regional agenda with border governors and neighbors.",
  "Laços com partidos e governos afins na região. Aproxima uns, afasta outros.": "Ties with like-minded parties and governments in the region. Brings some closer, pushes others away.",
  "Encontros regulares com lideranças religiosas e suas bancadas.": "Regular meetings with religious leaders and their caucuses.",
  "Propostas duras contra o crime organizado. Popular, polêmica entre movimentos sociais.": "Tough proposals against organized crime. Popular, controversial among social movements.",
  "Estrutura profissional de conteúdo e mobilização digital. Alcance enorme, atrito com tribunais e plataformas.": "A professional content and digital-mobilization operation. Huge reach, friction with courts and platforms.",
  "Entrevistas, coletivas e menos ataques a jornalistas.": "Interviews, press conferences and fewer attacks on journalists.",
  "Projetos de valores familiares e religiosos como bandeira da oposição.": "Family- and religious-values bills as the opposition's banner.",
