  ", que torna o Sul seu aliado.": ", which makes the South your ally.",
  "Clique na barra para ver o que sobe, o que baixa e agir.": "Click the bar to see what raises it, what lowers it, and to act.",
  "Ações do governo por área (após o golpe, também": "Government actions by area (after the coup, also",
  "). Cada uma mostra o custo (": "). Each one shows the cost (",
  "A Liga do Sul se rebela": "The Southern League rebels",
  "Os governadores do Sul rompem com Brasília. A revolta começa pequena — um estado e um exército modesto — e ainda pode ser contida.": "The Southern governors break with Brasília. The revolt starts small — one state and a modest army — and can still be contained.",
  "Armistício no Sul": "Armistice in the South",
  "Os governadores do Sul aceitam baixar as armas. Os estados rebelados voltam ao seu controle.": "The Southern governors agree to lay down their arms. The rebel states return to your control.",
  "O exército separatista foi dissolvido.": "The separatist army was disbanded.",
  "Os governadores do Sul assinam o pacto: mais autonomia em troca de lealdade. A rebelião do Sul está descartada.": "The Southern governors sign the pact: more autonomy in exchange for loyalty. A Southern rebellion is off the table.",
  "A Tensão no Sul deixa de importar: o Sul é seu aliado.": "Southern Tension no longer matters: the South is your ally.",
  "A Liga do Sul cai": "The Southern League falls",
  "Não resta nenhum estado sob controle separatista. A revolta do Sul acabou.": "No state remains under separatist control. The Southern revolt is over.",
  "Cúpula de Porto Alegre": "Porto Alegre Summit",
  "Os governadores do Rio Grande do Sul, de Santa Catarina e do Paraná pedem uma reunião de emergência. Querem verbas, autonomia fiscal e garantias de que Brasília não mandará interventores.": "The governors of Rio Grande do Sul, Santa Catarina and Paraná call for an emergency meeting. They want funds, fiscal autonomy and guarantees that Brasília will not send federal interventors.",
  "Se nada mudar, dizem, não respondem pelo que a Liga do Sul fará.": "If nothing changes, they say, they cannot answer for what the Southern League will do.",
  "Aceitar o acordo: verbas e autonomia fiscal para o Sul.": "Accept the deal: funds and fiscal autonomy for the South.",
  "Prometer estudar as demandas.": "Promise to study the demands.",
  "Ameaçar com intervenção federal.": "Threaten federal intervention.",
  "A Liga do Sul manda emissários": "The Southern League sends envoys",
  "Os separatistas do Sul propõem um pacto de não agressão enquanto você enfrenta a resistência.": "The Southern separatists propose a non-aggression pact while you fight the resistance.",
  "Ameaçar com uma ofensiva.": "Threaten an offensive.",
  "A Liga do Sul cobra a fatura": "The Southern League sends the bill",
  "Os separatistas exigem autonomia fiscal e comando próprio em troca da trégua.": "The separatists demand fiscal autonomy and their own command in exchange for the truce.",
  "Ceder e manter a trégua.": "Give in and keep the truce.",
  "Romper o pacto.": "Break the pact.",
  "O que se temia acontece: o comando militar do Nordeste e unidades da Marinha declaram lealdade ao governo constitucional. Generais que antes hesitavam agora escolhem lados. Amazonas e Amapá passam para a resistência. E no Sul, os governadores do Rio Grande do Sul e de Santa Catarina — a chamada Liga do Sul — observam o racha e medem até onde Brasília ainda manda neles.": "What everyone feared happens: the Northeast military command and Navy units declare loyalty to the constitutional government. Generals who once hesitated now pick sides. Amazonas and Amapá go over to the resistance. And in the South, the governors of Rio Grande do Sul and Santa Catarina — the so-called Southern League — watch the split and weigh how far Brasília still commands them.",
  "A frente de batalha corta Minas Gerais e o oeste da Bahia. A economia está em colapso; milhares de famílias fogem para o Paraguai, a Bolívia e o Uruguai. No Sul, a Liga do Sul mede forças com Brasília: se a tensão passar do limite, ela abre uma terceira frente.": "The front line cuts through Minas Gerais and western Bahia. The economy is collapsing; thousands of families flee to Paraguay, Bolivia and Uruguay. In the South, the Southern League is testing Brasília: if tension crosses the limit, it opens a third front.",
  "A frente de batalha corta Minas Gerais e o oeste da Bahia. A economia está em colapso; milhares de famílias fogem para o Paraguai, a Bolívia e o Uruguai. No Sul, o Pacto Federativo segura: as brigadas gaúchas e catarinenses lutam ao lado de Brasília.": "The front line cuts through Minas Gerais and western Bahia. The economy is collapsing; thousands of families flee to Paraguay, Bolivia and Uruguay. In the South, the Federal Pact holds: brigades from Rio Grande do Sul and Santa Catarina fight alongside Brasília.",
  "A frente de batalha corta Minas Gerais e o oeste da Bahia. A economia está em colapso; milhares de famílias fogem para o Paraguai, a Bolívia e o Uruguai. No Sul, a Liga do Sul abriu uma terceira frente.": "The front line cuts through Minas Gerais and western Bahia. The economy is collapsing; thousands of families flee to Paraguay, Bolivia and Uruguay. In the South, the Southern League has opened a third front.",
  "O cessar-fogo vira fronteira. Brasília controla o Centro-Sul e o Sul — os governadores sulistas nunca romperam —; o governo constitucional fica com o Norte e o Nordeste. Minas Gerais continua cortada por trincheiras.": "The ceasefire becomes a border. Brasília controls the Center-South and the South — the southern governors never broke away —; the constitutional government keeps the North and Northeast. Minas Gerais remains cut by trenches.",
  "Duas Bandeiras": "Two Flags",
  "A revolta da Liga do Sul foi esmagada: não resta estado sob controle separatista.": "The Southern League revolt was crushed: no state remains under separatist control.",
  "Pacto Federativo assinado: o Sul agora é aliado e enviou uma divisão.": "Federal Pact signed: the South is now an ally and sent a division.",
  "Os governadores do Sul pedem uma cúpula: veja a aba História.": "The Southern governors ask for a summit: see the Story tab.",
