  "Dificuldade (veja em Configurações)": "Difficulty (see Settings)",
  "Fácil": "Easy",
  "Difícil": "Hard",
  "Dificuldade": "Difficulty",
  "Para quem nunca jogou estratégia: inimigo mais fraco, Sul mais calmo, mais Recursos e uma interface mais simples. Os exércitos lutam sozinhos.": "For people who have never played strategy games: weaker enemy, calmer South, more Resources and a simpler interface. Armies fight on their own.",
  "O jogo como foi pensado: decisões com peso e guerra equilibrada.": "The game as designed: weighty decisions and a balanced war.",
  "Inimigo mais forte, menos Recursos e o Sul mais inquieto. Para quem já conhece o jogo.": "Stronger enemy, fewer Resources and a more restless South. For players who already know the game.",
  "Recomendado para começar": "Recommended to start",
  "Cerca de 12 a 20 meses de jogo (turnos). A história no ritmo normal.": "About 12 to 20 turns. The story at its normal pace.",
  "Cerca de 8 a 11 turnos (20 a 30 minutos). O tempo passa mais depressa e os eventos-chave chegam antes.": "About 8 to 11 turns (20 to 30 minutes). Time moves faster and key events come sooner.",
  "No Fácil, a interface fica mais simples: os exércitos agem sozinhos, a conversão de Recursos some e as escolhas que encerram a campanha avisam antes.": "On Easy the interface is simpler: armies act on their own, the Resource conversion is hidden and choices that end the campaign warn you first.",
  "A dificuldade fica fixa até o fim da campanha. Você pode conferir qual é em Configurações.": "The difficulty stays fixed until the end of the campaign. You can check it in Settings.",
  "Começar uma nova campanha substitui a campanha salva.": "Starting a new campaign replaces the saved one.",
  "Começar": "Start",
  "Campanha atual": "Current campaign",
  "Interface simples": "Simple interface",
  "— exércitos no automático, conversão de Recursos escondida e Diplomacia/Facções em “Mais”": "— armies on automatic, Resource conversion hidden and Diplomacy/Factions under “More”",
  "A dificuldade e a duração são escolhidas ao começar uma campanha e não mudam no meio dela.": "Difficulty and length are chosen when a campaign starts and don't change midway.",
  "Mais ▾": "More ▾",
  "Menos ▴": "Less ▴",
  "Seus exércitos lutam sozinhos.": "Your armies fight on their own.",
  "Todo mês, quem está sem ordem ataca onde a chance é boa e defende o resto.": "Every month, armies without orders attack where the odds are good and defend elsewhere.",
  "Todo mês, quem está sem ordem defende as fronteiras.": "Every month, armies without orders defend the borders.",
  "As ordens automáticas estão desligadas.": "Automatic orders are off.",
  "Seus exércitos vão ficar parados.": "Your armies will stay put.",
  "🤖 Ligar ordens automáticas": "🤖 Turn on automatic orders",
  "Comandar manualmente": "Command manually",
  "← Voltar ao resumo simples": "← Back to the simple summary",
  "Modo simples: seus exércitos agem sozinhos. Clique num estado para ver detalhes e agir nele.": "Simple mode: your armies act on their own. Click a state to see details and act there.",
  "Modo simples: seus exércitos agem sozinhos. Toque num estado para ver detalhes e agir nele.": "Simple mode: your armies act on their own. Tap a state to see details and act there.",
  "⚠ Encerra a campanha agora": "⚠ Ends the campaign now",
  "🏁 Encerra a campanha agora": "🏁 Ends the campaign now",
  "final intermediário": "middle ending",
  "No Fácil, a interface é simples: os exércitos agem sozinhos e Diplomacia e Facções ficam no botão “Mais”. Dá para mudar isso em Configurações.": "On Easy the interface is simple: armies act on their own and Diplomacy and Factions sit behind the “More” button. You can change this in Settings.",
  "Exércitos no automático": "Armies on automatic",
  "No modo simples, seus exércitos agem sozinhos todo mês: atacam onde a chance é boa e defendem o resto. Você só precisa recrutar quando quiser mais tropas.": "In simple mode your armies act on their own every month: they attack where the odds are good and defend elsewhere. You only need to recruit when you want more troops.",
  "Quer controlar cada exército? Clique em “Comandar manualmente”.": "Want to control each army? Click “Command manually”.",
