  "Aceite o resultado e, no fim, escolha comandar a direita sem disputar o cargo (ou perca a eleição de 2026).": "Accept the result and, at the end, choose to lead the right without running for office (or lose the 2026 election).",
  "Deixe o Apoio Popular chegar a zero, ou insista na própria candidatura depois de ficar inelegível.": "Let Popular Support hit zero, or insist on your own candidacy after being barred from running.",
