  "O rosto no cartão mostra quem está falando com você. São personagens inventados; pessoas reais e instituições aparecem só como ícone ou silhueta.": "The face on the card shows who is talking to you. They are made-up characters; real people and institutions only appear as an icon or a silhouette.",
  "Chefe de gabinete · estrategista": "Chief of staff · strategist",
  "Duas portas": "Two doors",
  "Convocar os comandantes": "Summon the commanders",
  "Ainda dá tempo": "There is still time",
  "Ninguém assinou nada ainda. Se o senhor quiser virar a mesa antes da posse, começamos por aqui:": "Nobody has signed anything yet. If you want to turn the tables before the inauguration, we start here:",
  "A sala sem celulares": "The room without phones",
  "Leia a sala antes de assinar qualquer coisa. Se os quartéis ainda hesitam, troque o comando primeiro.": "Read the room before signing anything. If the barracks still hesitate, replace the command first.",
  "Sem volta": "No way back",
  "A pergunta que importa": "The only question that matters",
  "Agora tudo depende das tropas. Se o Apoio Militar estiver alto, cerque. Se não, nada salva o plano.": "Now it all depends on the troops. If Military Support is high, surround them. If not, nothing saves the plan.",
  "O dia seguinte": "The day after",
  "O golpe passou, mas o país não obedece em bloco. Prometa eleições: acalma o Sul e os vizinhos, e os quartéis aguentam.": "The coup went through, but the country doesn't obey as one. Promise elections: it calms the South and the neighbors, and the barracks can take it.",
  "O plano, passo a passo": "The plan, step by step",
  "Primeiro, um balanço discreto da derrota. Ninguém conspira sem saber quem ainda atende o telefone:": "First, a quiet assessment of the defeat. Nobody conspires without knowing who still picks up the phone:",
  "Abra o caminho. Conversas reservadas, sem atas:": "Open the path. Private talks, no minutes:",
  "Os comandantes precisam se sentir parte disso:": "The commanders need to feel part of this:",
  "Deixe o papel pronto. Quando a hora chegar, não haverá tempo de redigir nada:": "Have the paper ready. When the time comes, there will be no time to draft anything:",
  "Os quartéis primeiro": "The barracks first",
  "Quem segura o regime depois": "Who holds the regime up afterwards",
  "O Sul está fervendo": "The South is boiling",
  "O mundo está olhando": "The world is watching",
  "Dinheiro para a guerra": "Money for the war",
