  "Você não move exércitos: escolha a postura de cada frente e encerre o mês.": "You do not move armies: choose each front's posture and end the month.",
  ", da economia, das tropas no estado e de haver guerra por perto.": ", the economy, troops in the state and whether there is fighting nearby.",
  "O governador de um estado na linha de frente manda emissários: aceita apoiar o regime em troca de verbas e cargos.": "The governor of a front-line state sends envoys: he agrees to support the regime in exchange for funds and posts.",
  "Capital e reduto só caem com o cerco completo; enquanto isso, a linha toma as regiões em volta.": "The capital and the stronghold only fall after a complete siege; meanwhile the line takes the regions around them.",
  "Brasília": "Brasília",
  "Recife": "Recife",
