  "Caminho mais curto até Porto Alegre": "Shortest path to Porto Alegre",
  "Rompimento!": "Breakthrough!",
  "Rompimento inimigo!": "Enemy breakthrough!",
  "Rompimento": "Breakthrough",
  "você segurou e a linha se estabilizou": "you held and the line stabilized",
  "o inimigo segurou e a linha dele se estabilizou": "the enemy held and their line stabilized",
  "sem novo rompimento neste mês.": "no new breakthrough this month.",
  "Com 1,5× ou mais de força e o mês ganho, a linha inimiga rompe e você avança várias regiões seguidas rumo à capital deles.": "With 1.5× or more strength and the month won, the enemy line breaks and you advance several regions in a row toward their capital.",
  "Rompimento: com força 1,5× maior e o mês ganho, a linha desaba e avança várias regiões seguidas rumo ao alvo. Quem segura a linha logo depois estabiliza.": "Breakthrough: with 1.5× the strength and the month won, the line collapses and the attacker advances several regions in a row toward the target. Whoever holds the line right after stabilizes it.",
  "Recife é a capital da Resistência: o governo constitucional se instalou no Palácio do Campo das Princesas.": "Recife is the capital of the Resistance: the constitutional government has set up in the Campo das Princesas Palace.",
  "Recife, capital da Resistência": "Recife, capital of the Resistance",
  "No Palácio do Campo das Princesas, governadores, parlamentares e comandantes leais à Constituição declaram instalado no Recife o governo constitucional. A partir de hoje o Brasil tem duas capitais — e a guerra, dois alvos.": "At the Campo das Princesas Palace, governors, lawmakers and commanders loyal to the Constitution declare the constitutional government installed in Recife. From today Brazil has two capitals — and the war, two targets.",
  "Vitória: tomar a região de Recife (PE) — a estrela vermelha no mapa.": "Victory: take the Recife region (PE) — the red star on the map.",
  "Derrota: perder a região de Brasília (DF).": "Defeat: losing the Brasília region (DF).",
  "O cartão da frente mostra quantas regiões faltam até Recife pelo caminho mais curto. Com força 1,5× maior, a linha inimiga pode romper.": "The front card shows how many regions are left to Recife along the shortest path. With 1.5× the strength, the enemy line can break.",
  "Recife e Brasília": "Recife and Brasília",
  "Na guerra, a resistência instala o governo constitucional no Recife. Tomar a região de Recife vence a guerra; perder Brasília (DF) é a derrota. A Liga do Sul tem capital em Porto Alegre. O cartão da frente mostra quantas regiões faltam até lá, e o mapa mostra o caminho mais curto.": "In the war, the resistance installs the constitutional government in Recife. Taking the Recife region wins the war; losing Brasília (DF) is defeat. The Southern League's capital is Porto Alegre. The front card shows how many regions are left to get there, and the map shows the shortest path.",
  "Com força 1,5× maior e o mês ganho, a linha inimiga desaba e o atacante avança várias regiões seguidas rumo à capital, sempre por regiões vizinhas. Quem segura a linha logo depois estabiliza a frente.": "With 1.5× the strength and the month won, the enemy line collapses and the attacker advances several regions in a row toward the capital, always through neighboring regions. Whoever holds the line right after stabilizes the front.",
  "Zoom do mapa": "Map zoom",
  "Roda do mouse, gesto de pinça ou os botões + e − aproximam o mapa; arraste para mover; ⟲ volta ao mapa inteiro. Com o mapa selecionado, as teclas + e − e as setas também funcionam.": "Mouse wheel, pinch gesture or the + and − buttons zoom the map; drag to move; ⟲ returns to the whole map. With the map selected, the + and − keys and the arrow keys also work.",
  "Aproximar o mapa": "Zoom in",
  "Afastar o mapa": "Zoom out",
  "Centralizar o mapa": "Reset map view",
  "Ir para Recife": "Go to Recife",
  "Ir para Porto Alegre": "Go to Porto Alegre",
