  "Você estava mais fraco, mas teve sorte e tomou a região.": "You were weaker, but got lucky and took the region.",
  "Você atacou sem força suficiente: o ataque foi repelido.": "You attacked without enough strength: the attack was repelled.",
  "A batalha foi equilibrada e o ataque foi repelido.": "The battle was close and the attack was repelled.",
