  ". Abaixo de {0}: +{1}.": ". Below {0}: +{1}.",
  "(o estado entra em disputa); fora dela, grandes protestos (−{0} de apoio) ou até perder o estado.": "(the state becomes contested); otherwise, mass protests (−{0} support) or even losing the state.",
