  "Legenda da agitação: de {0}, calmo, a {1}, revolta": "Unrest legend: from {0}, calm, to {1}, revolt",
  "({0}–{1}) = tensão em cada estado.": "({0}–{1}) = tension in each state.",
  "= revolta. Média acima de {0} derruba seu apoio; acima de {1}, revolta.": "= revolt. Average above {0} hurts your support; above {1}, revolt.",
  "Escolha um governo ou organismo para ver interesses e propor um acordo. Cada proposta custa {0} ponto de ação; a resposta depende da opinião, dos interesses deles, da sua legitimidade e da sua força.": "Pick a government or body to see its interests and propose a deal. Each proposal costs {0} action point; the answer depends on their opinion, their interests, your legitimacy and your strength.",
  "Leal ≥ {0}": "Loyal ≥ {0}",
  "Bônus de Recursos (≥{0}) e de atributos (≥{1}), conforme a facção.": "Resource bonus (≥{0}) and attribute bonus (≥{1}), depending on the faction.",
  "Neutra {0}–{1}": "Neutral {0}–{1}",
  "Insatisfeita {0}–{1}": "Discontent {0}–{1}",
  "A partir de {0} ou menos, o bônus vira penalidade.": "At {0} or below, the bonus becomes a penalty.",
  "Em crise < {0}": "In crisis < {0}",
  "Se a influência for {0} ou mais:": "If influence is {0} or more:",
  "(greves, defecções, rebeliões, até golpe), no máximo uma a cada {0} meses.": "(strikes, defections, rebellions, even a coup), at most one every {0} months.",
  ": {0} Recursos · sem gastar ações. Lealdade +{1}; rivais perdem {2}. Para manter aliados acima de {3}–{4} e colher os bônus.": ": {0} Resources · no actions spent. Loyalty +{1}; rivals lose {2}. To keep allies above {3}–{4} and reap the bonuses.",
  ": {0} Recursos · sem gastar ações. Influência −{1} e lealdade −{2}. Uma facção hostil com influência abaixo de {3} não provoca crise.": ": {0} Resources · no actions spent. Influence −{1} and loyalty −{2}. A hostile faction with influence below {3} causes no crisis.",
  "moral máxima das tropas {0}": "max troop morale {0}",
  "({0} Recursos · sem gastar ações): lealdade +{1}; Judiciário −{2} de lealdade (rival).": "({0} Resources · no actions spent): loyalty +{1}; Judiciary −{2} loyalty (rival).",
  "({0} Recursos · sem gastar ações): influência −{1} e lealdade −{2}. Útil para tirar uma facção hostil do jogo: com influência abaixo de {3} ela não provoca crises.": "({0} Resources · no actions spent): influence −{1} and loyalty −{2}. Useful to take a hostile faction out of play: with influence below {3} it causes no crises.",
  "Leal (≥{0}):": "Loyal (≥{0}):",
  "Apoio Militar +{0}/mês.": "Military Support +{0}/mo.",
  "Insatisfeita (≤{0}):": "Discontent (≤{0}):",
  "a lealdade define a moral máxima dos seus exércitos; ≥{0} dá +{1} ordem por mês e abaixo de {2}, −{3}.": "loyalty sets your armies' max morale; ≥{0} gives +{1} order per month and below {2}, −{3}.",
  "Todo mês, a lealdade volta {0}% em direção ao ponto de partida ({1}).": "Every month, loyalty moves {0}% back toward its starting point ({1}).",
