  "Enfraquecer ({0} Recursos)": "Weaken ({0} Resources)",
  "nenhum efeito agora (só bônus a partir de {0}–{1} ou penalidades a partir de {2})": "no effect now (bonus only from {0}–{1} or penalties from {2})",
  "({0} Recursos · sem gastar ações): lealdade +{1}.": "({0} Resources · no actions spent): loyalty +{1}.",
