  ": {0} para agradar, {1} para enfraquecer —": ": {0} to please, {1} to weaken —",
  ": {0} → +{1} ação ({2}×/turno).": ": {0} → +{1} action ({2}×/turn).",
  "Abaixo de zero, você perde {0} de Apoio Popular por mês.": "Below zero, you lose {0} Popular Support per month.",
  "Pontos de ação do turno. Quase tudo custa {0} AP. Recarregam a cada mês e não acumulam. Em {1}: {2} de base, {3} com Apoio Popular {4}+, {5} com {6}+; +{7} comprando com Recursos ({8}×/turno).": "Action points for the turn. Almost everything costs {0} AP. They refill every month and don't carry over. In {1}: {2} base, {3} with Popular Support {4}+, {5} with {6}+; +{7} by buying with Resources ({8}×/turn).",
  "opinião pública. Alto acalma os estados e, em {0}, dá mais ações por turno ({1}+ → {2}, {3}+ → {4}); baixo alimenta protestos e revoltas. Se chegar a zero, a campanha termina.": "public opinion. High calms the states and, in {0}, gives more actions per turn ({1}+ → {2}, {3}+ → {4}); low feeds protests and revolts. If it hits zero, the campaign ends.",
  "Tensão em cada estado ({0}–{1}). Média acima de {2} nos seus estados derruba o apoio; um estado acima de {3} sem tropas pode se revoltar. Investir, fazer propaganda e negociar com o governador baixam a agitação.": "Tension in each state ({0}–{1}). An average above {2} in your states hurts support; a state above {3} without troops may revolt. Investing, propaganda and deals with the governor lower unrest.",
  "Lealdade (do seu lado?) e influência (quanto pesam). Lealdade abaixo de {0} com influência {1} ou mais gera crises.": "Loyalty (on your side?) and influence (how much they weigh). Loyalty below {0} with influence {1} or more causes crises.",
  "(em fases calmas, até {0} meses).": "(in calm phases, up to {0} months).",
  "{0} de base; com": "{0} base; with",
  "Apoio Popular {0}+": "Popular Support {0}+",
  "são {0}, e com": "it's {0}, and with",
  "são {0}. Também dá para": "it's {0}. You can also",
  "comprar +{0}": "buy +{0}",
  "Teto de {0}:": "Cap of {0}:",
  ": opinião pública. Alto acalma os estados e, em {0}, dá mais ações por turno ({1}+ → {2}, {3}+ → {4}); baixo alimenta protestos e revoltas.": ": public opinion. High calms the states and, in {0}, gives more actions per turn ({1}+ → {2}, {3}+ → {4}); low feeds protests and revolts.",
  "Vão de {0} a {1}.": "They range from {0} to {1}.",
  "Cria um novo exército por alguns Recursos, sem AP (até {0} por mês). Exércitos fracos em descanso no seu território também se reforçam sozinhos.": "Creates a new army for some Resources, no AP (up to {0} per month). Weak armies resting in your territory also reinforce themselves.",
  "({0} AP); ele avança a cada mês e, ao concluir, aplica efeitos e libera ações, eventos e opções.": "({0} AP); it advances every month and, when done, applies effects and unlocks actions, events and options.",
  "lealdade abaixo de {0} com influência {1} ou mais provoca uma": "loyalty below {0} with influence {1} or more triggers a",
  "que têm de você (−{0} a +{1}). Escolha um para negociar.": "they have of you (−{0} to +{1}). Pick one to negotiate.",
  "mostra a chance antes de propor ({0} AP). A": "shows the odds before proposing ({0} AP). A",
  "Você não impediu a transição. A equipe do presidente eleito assume os ministérios e, em {0}º de janeiro, a faixa presidencial muda de dono. O comando do país começa a escapar das suas mãos.": "You did not stop the transition. The president-elect's team takes over the ministries and, on January {0}, the presidential sash changes owner. Command of the country starts slipping from your hands.",
  "A posse acontece em {0}º de janeiro. Uma semana depois, milhares de manifestantes invadem e depredam as sedes do Congresso, do Planalto e do STF. As imagens correm o mundo; líderes estrangeiros condenam o ataque em uníssono.": "The inauguration takes place on January {0}. A week later, thousands of rioters storm and vandalize the seats of Congress, the Planalto and the Supreme Court. The images go around the world; foreign leaders condemn the attack in unison.",
  "O Brasil, que entrou em {0} como um país polarizado, agora corre o risco de não ser mais um país.": "Brazil, which entered {0} as a polarized country, now risks no longer being a country.",
  "Por maioria, o tribunal declara você inelegível por oito anos. A decisão cai como uma bomba na direita: governadores, pastores, empresários e deputados começam a se perguntar quem herdará os seus votos em {0}.": "By majority, the court declares you ineligible for eight years. The decision lands like a bomb on the right: governors, pastors, business leaders and congressmen start wondering who will inherit your votes in {0}.",
  "Escolher e apoiar um herdeiro político para {0}.": "Choose and back a political heir for {0}.",
  "Dica {0} de {1}": "Tip {0} of {1}",
  "Próximo ({0}/{1})": "Next ({0}/{1})",
