  "{0}/mês": "{0}/month",
  "-{0}/mês": "-{0}/month",
  "o golpe em si, o racha nas Forças (+{0} de uma vez), agitação alta em RS/SC/PR, agronegócio insatisfeito, Apoio Militar baixo (<{1}), ameaças e intervenções.": "the coup itself, the split in the Armed Forces (+{0} at once), high unrest in RS/SC/PR, unhappy agribusiness, low Military Support (<{1}), threats and interventions.",
  "(−{0}) em RS/SC/PR no mapa, exércitos seus estacionados no Sul, agradar o agronegócio e escolher negociar nos eventos.": "(−{0}) in RS/SC/PR on the map, your armies stationed in the South, pleasing agribusiness and choosing to negotiate in events.",
  "e, com a tensão em {0} ou menos, assine o": "and, with tension at {0} or less, sign the",
  "Ela começou só pelo Rio Grande do Sul, com um exército pequeno (força {0}). Se a tensão ficar acima de {1}, Santa Catarina adere.": "It started only in Rio Grande do Sul, with a small army (strength {0}). If tension stays above {1}, Santa Catarina joins.",
  "Se você baixar a tensão para {0} ou menos, ela aceita um armistício": "If you bring tension down to {0} or less, it accepts an armistice",
  "Rio Grande do Sul passou para a Liga do Sul, com um exército de força {0}.": "Rio Grande do Sul went over to the Southern League, with an army of strength {0}.",
  "Se a tensão ficar acima de {0} por {1} meses, Santa Catarina também adere.": "If tension stays above {0} for {1} months, Santa Catarina joins as well.",
  "Saída política: baixe a Tensão no Sul para {0} ou menos (ações da categoria Sul, investir/negociar em RS/SC/PR) e eles aceitam um armistício.": "Political way out: bring Southern Tension down to {0} or less (South actions, invest/negotiate in RS/SC/PR) and they accept an armistice.",
  "A tensão recomeça em {0}. Cuide dela para não haver uma segunda revolta.": "Tension restarts at {0}. Keep it in check to avoid a second revolt.",
  "Na guerra, a Divisão Blindada do Sul (força {0}) luta do seu lado.": "In the war, the Southern Armored Division (strength {0}) fights on your side.",
  "Tensão no Sul: {0} → {1}. Clique na barra “Tensão no Sul” para ver como baixá-la.": "Southern Tension: {0} → {1}. Click the “Southern Tension” bar to see how to lower it.",
  "Só se a Liga do Sul se rebelar (Tensão no Sul chega a {0}).": "Only if the Southern League rebels (Southern Tension reaches {0}).",
  "Trégua de conveniência com os separatistas: reconhece fato consumado e divide o comando. Derruba a Tensão no Sul (−{0}), o que pode levar a um armistício.": "A truce of convenience with the separatists: accepts the fait accompli and shares command. Cuts Southern Tension (−{0}), which can lead to an armistice.",
  "Tensão no Sul {0}": "Southern Tension {0}",
  "Tensão no Sul +{0}": "Southern Tension +{0}",
  "Tensão no Sul -{0}": "Southern Tension -{0}",
  "Tensão no Sul −{0}": "Southern Tension −{0}",
  "O Sul vira aliado (+{0} exército de {1})": "The South becomes an ally (+{0} army of {1})",
  "⚠ Tensão no Sul em {0}/{1} (+{2} no turno): no ritmo atual a Liga do Sul se rebela em ~{3} meses. Use as ações da categoria Sul (aba Ações) ou invista em RS/SC/PR.": "⚠ Southern Tension at {0}/{1} (+{2} this turn): at the current pace the Southern League rebels in ~{3} months. Use the South actions (Actions tab) or invest in RS/SC/PR.",
  "⚠ Tensão no Sul em {0}/{1} (-{2} no turno): no ritmo atual a Liga do Sul se rebela em ~{3} meses. Use as ações da categoria Sul (aba Ações) ou invista em RS/SC/PR.": "⚠ Southern Tension at {0}/{1} (-{2} this turn): at the current pace the Southern League rebels in ~{3} months. Use the South actions (Actions tab) or invest in RS/SC/PR.",
  "⚠ Tensão no Sul em {0}/{1} (+{2} no turno). Use as ações da categoria Sul (aba Ações) ou invista em RS/SC/PR.": "⚠ Southern Tension at {0}/{1} (+{2} this turn). Use the South actions (Actions tab) or invest in RS/SC/PR.",
  "A Liga do Sul se rebelou: Rio Grande do Sul rompe com Brasília (um exército separatista pequeno, força {0}). Santa Catarina pode aderir em {1} meses se a tensão continuar alta.": "The Southern League has rebelled: Rio Grande do Sul breaks with Brasília (a small separatist army, strength {0}). Santa Catarina may join in {1} months if tension stays high.",
  "A Liga do Sul segue em revolta (tensão {0}/{1}). Se continuar acima de {2}, Santa Catarina adere em breve. Com {3} ou menos, ela aceita um armistício.": "The Southern League remains in revolt (tension {0}/{1}). If it stays above {2}, Santa Catarina joins soon. At {3} or less, it accepts an armistice.",
  "A Liga do Sul segue em revolta (tensão {0}/{1}). Com {2} ou menos, ela aceita um armistício.": "The Southern League remains in revolt (tension {0}/{1}). At {2} or less, it accepts an armistice.",
  "Santa Catarina adere à Liga do Sul (tensão {0}/{1}). Baixe a tensão para {2} ou menos para forçar um armistício.": "Santa Catarina joins the Southern League (tension {0}/{1}). Bring tension down to {2} or less to force an armistice.",
  "Armistício no Sul: a Liga do Sul depõe as armas e os estados rebeldes voltam ao seu controle. Tensão no Sul {0}/{1} — se voltar a {2}, ela se rebela de novo.": "Armistice in the South: the Southern League lays down its arms and the rebel states return to your control. Southern Tension {0}/{1} — if it gets back to {2}, it rebels again.",
  "O racha nas Forças inflama o Sul: Tensão no Sul +{0} (agora {1}/{2}).": "The split in the Armed Forces inflames the South: Southern Tension +{0} (now {1}/{2}).",
  "Tensão no Sul: {0}/{1} (+{2}).": "Southern Tension: {0}/{1} (+{2}).",
  "Tensão no Sul: {0}/{1} (-{2}).": "Southern Tension: {0}/{1} (-{2}).",
  "Tensão no Sul: {0}/{1} ({2}).": "Southern Tension: {0}/{1} ({2}).",
  "aqui baixa a Tensão no Sul em {0}, e": "here lowers Southern Tension by {0}, and",
  "com sucesso, em {0}.": "successfully, by {0}.",
