  "Avança sobre um estado vizinho inimigo ou em disputa. Gasta {0} manobra. Vários exércitos atacando o mesmo estado somam forças.": "Advances on a neighboring enemy or contested state. Uses {0} maneuver. Several armies attacking the same state combine their strength.",
  ": Avança sobre um estado vizinho inimigo ou em disputa. Gasta {0} manobra. Vários exércitos atacando o mesmo estado somam forças.": ": Advances on a neighboring enemy or contested state. Uses {0} maneuver. Several armies attacking the same state combine their strength.",
  "Leva o exército para um estado vizinho seu (ou recua de uma frente). Gasta {0} manobra.": "Moves the army to a neighboring state of yours (or retreats from a front). Uses {0} maneuver.",
  ": Leva o exército para um estado vizinho seu (ou recua de uma frente). Gasta {0} manobra.": ": Moves the army to a neighboring state of yours (or retreats from a front). Uses {0} maneuver.",
  "Fica onde está, com posições preparadas: +{0}% na defesa e +{1} de moral. Não gasta manobra.": "Stays put in prepared positions: +{0}% defense and +{1} morale. Uses no maneuver.",
  ": Fica onde está, com posições preparadas: +{0}% na defesa e +{1} de moral. Não gasta manobra.": ": Stays put in prepared positions: +{0}% defense and +{1} morale. Uses no maneuver.",
  "Fica parado e ganha +{0} de força no fim do mês. Custa dinheiro, só em território seu. Não gasta manobra.": "Stays put and gains +{0} strength at the end of the month. Costs money, only in your territory. Uses no maneuver.",
  ": Fica parado e ganha +{0} de força no fim do mês. Custa dinheiro, só em território seu. Não gasta manobra.": ": Stays put and gains +{0} strength at the end of the month. Costs money, only in your territory. Uses no maneuver.",
