  "No começo da campanha cada turno é uma quinzena ({0} dias): mais decisões antes da posse. Depois, cada turno vira um mês.": "At the start of the campaign each turn is a fortnight ({0} days): more decisions before the inauguration. After that, each turn becomes a month.",
  "Contestação das urnas: progresso {0}/{1} (+{2}) · credibilidade {3} · escalada {4}.": "Ballot challenge: progress {0}/{1} (+{2}) · credibility {3} · escalation {4}.",
  "Contestação das urnas: progresso {0}/{1} · credibilidade {2} · escalada {3}.": "Ballot challenge: progress {0}/{1} · credibility {2} · escalation {3}.",
  "Contestação das urnas: progresso {0} de {1}, credibilidade {2}, escalada {3}. Abrir detalhes.": "Ballot challenge: progress {0} of {1}, credibility {2}, escalation {3}. Open details.",
  "Julgamento no TSE: precisa de {0}": "TSE ruling: needs {0}",
  "Veredito: precisa de {0}": "Verdict: needs {0}",
  "Chegue a {0} para vencer": "Reach {0} to win",
  "Seu progresso está baixo para o julgamento de janeiro ({0}/{1}). Auditoria, ações no TSE e o Congresso rendem mais com credibilidade alta.": "Your progress is low for the January ruling ({0}/{1}). Audits, TSE lawsuits and Congress yield more with high credibility.",
  "As ruas estão no limite (escalada {0}). Mais um ato e os acampamentos viram caso de quartel. Use 'Baixar a temperatura' agora.": "The streets are at the limit (escalation {0}). One more rally and the camps become a matter for the barracks. Use 'Lower the temperature' now.",
  "Sua credibilidade está em {0}. Abaixo de zero, o TSE declara você inelegível. Pare com as redes e traga observadores ou peritos.": "Your credibility is at {0}. Below zero, the TSE declares you ineligible. Stop the social media push and bring in observers or experts.",
  "Está funcionando: {0}/{1} de progresso, credibilidade {2}, escalada {3}. Mantenha a frente dentro da lei.": "It's working: {0}/{1} progress, credibility {2}, escalation {3}. Keep the front within the law.",
  "Agora é pelas regras, mas é guerra de nervos. Três números: o progresso vence em {0}; a credibilidade não pode zerar, ou o TSE te torna inelegível; e a escalada não pode chegar a {1}, ou as ruas viram caso de quartel.": "Now it's by the rules, but it's a war of nerves. Three numbers: progress wins at {0}; credibility can't hit zero, or the TSE makes you ineligible; and escalation can't reach {1}, or the streets become a matter for the barracks.",
  "O TSE adiou a posse para auditar as seções. Até março, cada quinzena conta: leve o progresso a {0} sem perder a credibilidade.": "The TSE postponed the inauguration to audit the sections. Until March, every fortnight counts: take progress to {0} without losing credibility.",
  "Você está tentando virar o resultado sem guerra: auditorias, tribunais, Congresso e ruas, sempre dentro da lei. São três números de {0} a {1}:": "You are trying to overturn the result without war: audits, courts, Congress and the streets, always within the law. There are three numbers from {0} to {1}:",
  "Progresso {0}/{1}": "Progress {0}/{1}",
  "Credibilidade {0}": "Credibility {0}",
  "Escalada {0}": "Escalation {0}",
